package com.graduation.gym.domain;import com.graduation.gym.auth.AuthService;import com.graduation.gym.common.ApiException;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/memberships")public class GymMembershipController{private final GymMembershipRepository repo;private final MembershipPlanRepository plans;private final AuthService auth;public GymMembershipController(GymMembershipRepository r,MembershipPlanRepository p,AuthService a){repo=r;plans=p;auth=a;}public record Create(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long planId){}@PostMapping public GymMembership buy(@jakarta.validation.Valid @RequestBody Create x){var p=plans.findById(x.planId()).orElseThrow(()->ApiException.notFound("套餐不存在"));if(!"ACTIVE".equals(p.getStatus()))throw ApiException.badRequest("套餐不可用");var m=new GymMembership();m.setUserId(auth.currentUser().getId());m.setPlanId(p.getId());m.setStartDate(LocalDate.now());m.setEndDate(LocalDate.now().plusDays(p.getDurationDays()));m.setStatus("ACTIVE");return repo.save(m);}@GetMapping public List<GymMembership>list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}}
